Your expense tracker is below. Add an expense, set a monthly budget, and it shows your total and a split by category. I can't promise entries are kept after you close it, so note down the total before you leave.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:14px;background:#f7f7f5;color:#222}
  h2{margin:0 0 10px;font-size:18px}
  .card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
  .row{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:6px}
  input,select,button{font-size:14px;padding:7px;border:1px solid #ccc;border-radius:6px}
  input{flex:1;min-width:90px}
  button{background:#2f7d5b;color:#fff;border:none;cursor:pointer}
  button.x{background:none;color:#b33;padding:2px 6px}
  .big{font-size:24px;font-weight:600}
  .muted{color:#777;font-size:12px}
  .bar{height:8px;background:#e5e5e0;border-radius:4px;overflow:hidden;margin:3px 0 8px}
  .bar div{height:100%;background:#2f7d5b}
  .item{display:flex;justify-content:space-between;align-items:center;padding:5px 0;border-bottom:1px solid #eee;font-size:14px}
  .over{color:#b33}
</style>
</head>
<body>
<h2>Expenses this month</h2>

<div class="card">
  <div class="muted">Total spent</div>
  <div class="big" id="total">₹0</div>
  <div class="row" style="margin-top:8px">
    <input id="budget" type="number" placeholder="Monthly budget (₹)">
  </div>
  <div id="left" class="muted"></div>
</div>

<div class="card">
  <div class="row">
    <input id="desc" placeholder="What for?">
    <input id="amt" type="number" placeholder="Amount (₹)">
  </div>
  <div class="row">
    <select id="cat">
      <option>Food</option><option>Travel</option><option>Bills</option>
      <option>Shopping</option><option>Health</option><option>Other</option>
    </select>
    <button id="add">Add expense</button>
  </div>
</div>

<div class="card">
  <div class="muted" style="margin-bottom:6px">By category</div>
  <div id="cats"></div>
</div>

<div class="card">
  <div class="muted" style="margin-bottom:6px">All expenses</div>
  <div id="list"></div>
</div>

<script>
var items=[];
function inr(n){return '₹'+Number(n).toLocaleString('en-IN',{maximumFractionDigits:2});}
function render(){
  var total=0,by={};
  items.forEach(function(e){total+=e.a;by[e.c]=(by[e.c]||0)+e.a;});
  document.getElementById('total').textContent=inr(total);
  var b=parseFloat(document.getElementById('budget').value);
  var left=document.getElementById('left');
  if(b>0){
    var r=b-total;
    left.className='muted'+(r<0?' over':'');
    left.textContent=r>=0?inr(r)+' left of '+inr(b):inr(-r)+' over budget of '+inr(b);
  }else{left.textContent='';}
  var cats=document.getElementById('cats');cats.innerHTML='';
  Object.keys(by).sort(function(x,y){return by[y]-by[x];}).forEach(function(k){
    var d=document.createElement('div');
    var pct=total?Math.round(by[k]/total*100):0;
    d.innerHTML='<div style="display:flex;justify-content:space-between;font-size:14px"><span>'+k+'</span><span>'+inr(by[k])+' ('+pct+'%)</span></div><div class="bar"><div style="width:'+pct+'%"></div></div>';
    cats.appendChild(d);
  });
  if(!items.length)cats.innerHTML='<div class="muted">Nothing yet.</div>';
  var list=document.getElementById('list');list.innerHTML='';
  items.slice().reverse().forEach(function(e){
    var i=items.indexOf(e);
    var d=document.createElement('div');d.className='item';
    var s=document.createElement('span');
    s.textContent=(e.d||e.c)+' · '+e.c;
    var r=document.createElement('span');
    r.textContent=inr(e.a)+' ';
    var x=document.createElement('button');x.className='x';x.textContent='✕';
    x.onclick=function(){items.splice(i,1);render();};
    r.appendChild(x);d.appendChild(s);d.appendChild(r);list.appendChild(d);
  });
  if(!items.length)list.innerHTML='<div class="muted">Nothing yet.</div>';
}
document.getElementById('add').onclick=function(){
  var a=parseFloat(document.getElementById('amt').value);
  if(!(a>0))return;
  items.push({d:document.getElementById('desc').value.trim(),a:a,c:document.getElementById('cat').value});
  document.getElementById('desc').value='';document.getElementById('amt').value='';
  render();
};
document.getElementById('budget').oninput=render;
render();
</script>
</body>
</html>
```

